    SECTION code_user
    PUBLIC hex_digit

hex_digits:
    defb "0123456789ABCDEF"

; Convert the low four bits of A to an uppercase hexadecimal digit.
hex_digit:
    and 15
        ld e, a
        ld d, 0
        ld hl, hex_digits
        add hl, de
        ld a, (hl)
    ret
